import{_ as a,o,c as i,a2 as s}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Contenido Programático: Bases de Datos Avanzadas (Trayecto III - Ingeniería)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Bases_de_Datos_Avanzadas/Contenido_Programatico.md","filePath":"materias/Bases_de_Datos_Avanzadas/Contenido_Programatico.md"}'),d={name:"materias/Bases_de_Datos_Avanzadas/Contenido_Programatico.md"};function n(r,e,t,l,c,u){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="contenido-programatico-bases-de-datos-avanzadas-trayecto-iii-ingenieria" tabindex="-1">Contenido Programático: Bases de Datos Avanzadas (Trayecto III - Ingeniería) <a class="header-anchor" href="#contenido-programatico-bases-de-datos-avanzadas-trayecto-iii-ingenieria" aria-label="Permalink to &quot;Contenido Programático: Bases de Datos Avanzadas (Trayecto III - Ingeniería)&quot;">​</a></h1><p><strong>Institución:</strong> Universidad Politécnica Territorial del Estado Trujillo &quot;Mario Briceño Iragorry&quot; (UPTTMBI)<br><strong>Programa:</strong> Programa Nacional de Formación en Informática (PNFI)<br><strong>Título Conducente:</strong> Ingeniera o Ingeniero en Informática (Nivel: Desarrollador de Aplicaciones)<br><strong>Unidad Curricular:</strong> Bases de Datos Avanzadas <em>(Oficial: Modelado de Bases de Datos)</em><br><strong>Trayecto:</strong> III<br><strong>Trimestre:</strong> VIII (Segundo Trimestre del Trayecto III)<br><strong>Tipo:</strong> Curso<br><strong>Unidades Crédito (UC):</strong> 3<br><strong>Código:</strong> BDC313<br><strong>Densidad Horaria:</strong></p><ul><li>Horas de Trabajo del Estudiante Acompañado (HTEA): 5 horas semanales</li><li>Horas de Trabajo de Estudio Independiente (HTEI): 1,5 horas semanales</li><li>Total Horas de Trabajo del Estudiante (THTE): 6,5 horas semanales (78 horas por trimestre)</li></ul><hr><h2 id="🎯-proposito-general" tabindex="-1">🎯 PROPÓSITO GENERAL <a class="header-anchor" href="#🎯-proposito-general" aria-label="Permalink to &quot;🎯 PROPÓSITO GENERAL&quot;">​</a></h2><p>Capacitar al futuro Ingeniero en Informática en el diseño, implementación y optimización de arquitecturas de bases de datos avanzadas, dominando paradigmas objeto-relacionales, bases de datos activas (disparadores y procedimientos en el servidor), vistas materializadas, consultas analíticas de alto rendimiento y técnicas de indexación física para soportar aplicaciones empresariales a gran escala y proyectos sociotecnológicos de envergadura nacional.</p><hr><h2 id="🔌-saberes-y-contenido-analitico" tabindex="-1">🔌 SABERES Y CONTENIDO ANALÍTICO <a class="header-anchor" href="#🔌-saberes-y-contenido-analitico" aria-label="Permalink to &quot;🔌 SABERES Y CONTENIDO ANALÍTICO&quot;">​</a></h2><h3 id="unidad-1-metodologias-de-diseno-conceptual-avanzado-y-calidad-de-esquemas" tabindex="-1">Unidad 1: Metodologías de Diseño Conceptual Avanzado y Calidad de Esquemas <a class="header-anchor" href="#unidad-1-metodologias-de-diseno-conceptual-avanzado-y-calidad-de-esquemas" aria-label="Permalink to &quot;Unidad 1: Metodologías de Diseño Conceptual Avanzado y Calidad de Esquemas&quot;">​</a></h3><ul><li><strong>Modelado Conceptual en Ingeniería:</strong><ul><li>Abstracciones de datos: Agregación, Clasificación, Generalización y Asociación.</li><li>Análisis del Universo del Discurso en sistemas corporativos complejos.</li></ul></li><li><strong>Métricas de Calidad de Esquemas de Bases de Datos:</strong><ul><li>Completitud, minimalidad, expresividad y legibilidad.</li><li>Trade-offs de diseño: Normalización extrema vs. Desnormalización controlada para lectura masiva (OLAP / Data Marts básicos).</li></ul></li></ul><h3 id="unidad-2-paradigmas-de-bases-de-datos-y-el-modelo-objeto-relacional" tabindex="-1">Unidad 2: Paradigmas de Bases de Datos y el Modelo Objeto-Relacional <a class="header-anchor" href="#unidad-2-paradigmas-de-bases-de-datos-y-el-modelo-objeto-relacional" aria-label="Permalink to &quot;Unidad 2: Paradigmas de Bases de Datos y el Modelo Objeto-Relacional&quot;">​</a></h3><ul><li><strong>Evolución Más Allá de las Tablas Planas:</strong><ul><li>Limitaciones del modelo relacional puro ante estructuras no tabulares (impedancia objeto-relacional).</li><li>Paradigmas: Bases de Datos Orientadas a Objetos (OODBMS) vs. Sistemas Objeto-Relacionales (ORDBMS).</li></ul></li><li><strong>El Motor Objeto-Relacional en PostgreSQL:</strong><ul><li>Tipos de datos compuestos y tipos definidos por el usuario (<code>CREATE TYPE AS ENUM / OBJECT</code>).</li><li>Herencia de tablas (<code>INHERITS</code>).</li><li>Almacenamiento semiestructurado: columnas <code>JSON</code> y <code>JSONB</code> indexables, operadores de extracción (<code>-&gt;</code>, <code>-&gt;&gt;</code>, <code>@&gt;</code>).</li><li>Comparativa de integración: Cuándo usar relacional estricto y cuándo documentos JSON embebidos.</li></ul></li></ul><h3 id="unidad-3-bases-de-datos-activas-triggers-y-logica-en-el-servidor-pl-pgsql" tabindex="-1">Unidad 3: Bases de Datos Activas: Triggers y Lógica en el Servidor (PL/pgSQL) <a class="header-anchor" href="#unidad-3-bases-de-datos-activas-triggers-y-logica-en-el-servidor-pl-pgsql" aria-label="Permalink to &quot;Unidad 3: Bases de Datos Activas: Triggers y Lógica en el Servidor (PL/pgSQL)&quot;">​</a></h3><ul><li><strong>Concepto de Base de Datos Activa:</strong><ul><li>Paradigma Evento-Condición-Acción (ECA - <em>Event-Condition-Action</em>).</li><li>Diferencia arquitectónica entre lógica en el Backend (Node.js/Python) vs. lógica transaccional en el motor de base de datos.</li></ul></li><li><strong>Funciones y Procedimientos Almacenados:</strong><ul><li>Estructura del lenguaje procedimental <code>PL/pgSQL</code>.</li><li>Variables, estructuras condicionales (<code>IF-ELSE</code>), bucles (<code>LOOP</code>, <code>FOR</code>) y manejo de excepciones.</li></ul></li><li><strong>Disparadores (Triggers):</strong><ul><li>Momentos de disparo: <code>BEFORE</code>, <code>AFTER</code>, <code>INSTEAD OF</code>.</li><li>Granularidad: <code>FOR EACH ROW</code> vs. <code>FOR EACH STATEMENT</code>.</li><li>Variables de contexto: <code>NEW</code> y <code>OLD</code>.</li><li>Casos prácticos de uso: Auditoría automática de cambios (log de operaciones), cálculo de saldos y consistencia de reglas de negocio inviolables.</li></ul></li></ul><h3 id="unidad-4-consultas-sql-avanzadas-vistas-y-metricas-analiticas" tabindex="-1">Unidad 4: Consultas SQL Avanzadas, Vistas y Métricas Analíticas <a class="header-anchor" href="#unidad-4-consultas-sql-avanzadas-vistas-y-metricas-analiticas" aria-label="Permalink to &quot;Unidad 4: Consultas SQL Avanzadas, Vistas y Métricas Analíticas&quot;">​</a></h3><ul><li><strong>Subconsultas de Alta Complejidad:</strong><ul><li>Subconsultas escalares, subconsultas en la cláusula <code>FROM</code> (tablas derivadas).</li><li>Subconsultas correlacionadas y operadores <code>EXISTS</code>, <code>NOT EXISTS</code>, <code>ALL</code>, <code>ANY</code>.</li></ul></li><li><strong>Expresiones de Tabla Comunes (CTEs - Cláusula <code>WITH</code>):</strong><ul><li>Modularización y legibilidad de consultas complejas.</li><li>CTEs recursivas para estructuras jerárquicas (árboles de categorías, organigramas).</li></ul></li><li><strong>Vistas Estándar y Vistas Materializadas:</strong><ul><li>Creación y actualización de vistas (<code>CREATE VIEW</code>).</li><li>Vistas Materializadas (<code>CREATE MATERIALIZED VIEW</code>): persistencia física de resultados para reportes ultrarrápidos y estrategias de refresco (<code>REFRESH MATERIALIZED VIEW CONCURRENTLY</code>).</li></ul></li><li><strong>Introducción a Funciones de Ventana (Window Functions):</strong><ul><li>Cláusula <code>OVER (PARTITION BY ... ORDER BY ...)</code>.</li><li>Funciones de ranking y analítica: <code>ROW_NUMBER()</code>, <code>RANK()</code>, <code>DENSE_RANK()</code>, <code>LAG()</code>, <code>LEAD()</code>.</li></ul></li></ul><h3 id="unidad-5-optimizacion-fisica-indices-y-planes-de-ejecucion" tabindex="-1">Unidad 5: Optimización Física, Índices y Planes de Ejecución <a class="header-anchor" href="#unidad-5-optimizacion-fisica-indices-y-planes-de-ejecucion" aria-label="Permalink to &quot;Unidad 5: Optimización Física, Índices y Planes de Ejecución&quot;">​</a></h3><ul><li><strong>El Optimizador de Consultas:</strong><ul><li>Cómo el motor convierte SQL declarativo en un plan físico de acceso a disco.</li><li>Interpretación de planes de ejecución mediante <code>EXPLAIN</code> y <code>EXPLAIN ANALYZE</code>.</li><li>Tipos de escaneo: <em>Sequential Scan</em>, <em>Index Scan</em>, <em>Bitmap Index Scan</em>.</li><li>Métodos de unión física: <em>Nested Loop</em>, <em>Hash Join</em>, <em>Merge Join</em>.</li></ul></li><li><strong>Estrategias de Indexación:</strong><ul><li>Índices B-Tree (árboles balanceados estándar para igualdades y rangos).</li><li>Índices GIN (Generalized Inverted Index) para búsquedas de texto completo (<em>Full-Text Search</em>) y documentos <code>JSONB</code>.</li><li>Índices parciales (<code>CREATE INDEX ... WHERE condicion</code>) e índices compuestos.</li><li>Costo de los índices: Mantenimiento en operaciones de escritura (<code>INSERT</code>/<code>UPDATE</code>).</li></ul></li></ul><hr><h2 id="🛠️-estrategias-metodologicas" tabindex="-1">🛠️ ESTRATEGIAS METODOLÓGICAS <a class="header-anchor" href="#🛠️-estrategias-metodologicas" aria-label="Permalink to &quot;🛠️ ESTRATEGIAS METODOLÓGICAS&quot;">​</a></h2><ol><li><strong>Talleres de Ingeniería y Rendimiento:</strong> Laboratorios donde el estudiante debe optimizar consultas que procesan cientos de miles de registros simulados, reduciendo los tiempos de ejecución de segundos a milisegundos.</li><li><strong>Desarrollo de Triggers de Auditoría para el Proyecto Sociotecnológico III (PST-III):</strong> Implementación de sistemas de registro de trazas y seguridad que certifiquen quién, cuándo y qué modificó en la base de datos comunitaria.</li><li><strong>Benchmarking Comparativo:</strong> Pruebas controladas comparando rendimiento de vistas estándar vs. vistas materializadas indexadas.</li></ol><hr><h2 id="📖-referencias-bibliograficas" tabindex="-1">📖 REFERENCIAS BIBLIOGRÁFICAS <a class="header-anchor" href="#📖-referencias-bibliograficas" aria-label="Permalink to &quot;📖 REFERENCIAS BIBLIOGRÁFICAS&quot;">​</a></h2><ol><li><strong>Date, C. J.</strong> (2001). <em>Introducción a los sistemas de bases de datos</em> (7ª ed.). Pearson Educación.</li><li><strong>Elmasri, R., &amp; Navathe, S. B.</strong> (2007). <em>Sistemas de Bases de Datos: Conceptos Fundamentales</em> (5ª ed.). Addison-Wesley Iberoamericana.</li><li><strong>Garcia-Molina, H., Ullman, J. D., &amp; Widom, J.</strong> (2002). <em>Database Systems: The Complete Book</em>. Prentice Hall.</li><li><strong>PostgreSQL Global Development Group.</strong> (2026). <em>PostgreSQL Official Documentation (v15/v16)</em>. Chapter: PL/pgSQL, Triggers, Views &amp; Performance Optimization.</li><li><strong>Winand, M.</strong> (2012). <em>Use The Index, Luke!: A Guide to Database Performance for Developers</em>.</li><li><strong>Documento Rector del PNFI.</strong> (2010/2014). Ministerio del Poder Popular para la Educación Universitaria, Ciencia y Tecnología (MPPEUCT), Venezuela.</li></ol>',24)])])}const p=a(d,[["render",n]]);export{g as __pageData,p as default};
